import heapq

def match(orders):
    trades = []
    buy_heap = []  # max-heap by price: (-price, arrival, id)
    sell_heap = []  # min-heap by price: (price, arrival, id)
    book = {}  # id -> dict with side, price, qty, arrival, alive
    arrival_counter = 0

    def add_to_book(oid, side, price, qty, arrival):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'alive': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, oid))
        else:
            heapq.heappush(sell_heap, (price, arrival, oid))

    def pop_valid_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid]['alive'] and book[oid]['qty'] > 0:
                return item
            heapq.heappop(heap)
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['alive'] and book[oid]['qty'] > 0:
                book[oid]['alive'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = pop_valid_top(opp_heap)
            if top is None:
                break
            opp_price = top[0]
            opp_id = top[2]

            if typ == 'market':
                match_ok = True
            else:
                if side == 'buy':
                    match_ok = price >= opp_price
                else:
                    match_ok = price <= opp_price

            if not match_ok:
                break

            opp_order = book[opp_id]
            trade_qty = min(remaining, opp_order['qty'])
            trade_price = opp_order['price']

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            opp_order['qty'] -= trade_qty
            remaining -= trade_qty

            if opp_order['qty'] == 0:
                opp_order['alive'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, arrival)
        elif typ == 'limit' and remaining == 0:
            # fully filled at arrival, mark as inactive record for cancel safety
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'arrival': arrival, 'alive': False}

    return trades

